<!-- subpkg-patient/report/detail.vue — 病例详情，对齐 CaseDetail -->
<template><view class="page-shell"><NavBar title="病例详情" :showBack="true"/><scroll-view scroll-y class="body"><LoadingSkeleton v-if="loading"/><EmptyState v-else-if="error" icon="⚠️" :title="error"><button class="btn-p" @tap="load">重新加载</button></EmptyState><template v-else-if="data"><view class="hero mb-md"><text class="sec-kicker">病例详情</text><text class="hero-id">#{{data.id}}</text><view class="hero-stats"><view class="hs-item"><text class="hsv">{{fmtConf(data.confidence)}}</text><text class="hsl">总体置信度</text></view><view class="hs-item"><text class="hsv">{{data.findings?.length||0}}</text><text class="hsl">病灶发现</text></view></view></view><image v-if="imgUrl" :src="imgUrl" mode="aspectFit" class="detail-img"/><view class="card mb-md"><text class="card-title">基础信息</text><view class="info-grid"><view class="info-item" v-for="(v,k) in infoFields" :key="k"><text class="ii-label">{{k}}</text><text class="ii-val">{{v}}</text></view></view></view><view class="card" v-if="data.findings?.length"><text class="card-title">病灶发现 ({{data.findings.length}}项)</text><view class="finding-item" v-for="(f,i) in data.findings" :key="i"><text class="fi-type">{{f.type}}</text><text class="fi-loc" v-if="f.location">{{f.location}}</text><text class="fi-conf">{{fmtConf(f.confidence)}}</text></view></view></template></scroll-view></view></template>
<script setup>
import {ref,computed,onMounted} from 'vue';import NavBar from '@/components/nav-bar.vue';import LoadingSkeleton from '@/components/loading-skeleton.vue';import EmptyState from '@/components/empty-state.vue';import {medicalAPI} from '@/api/medical';import {ensureImageUrl} from '@/utils/image'
const loading=ref(true);const error=ref('');const data=ref(null)
const imgUrl=computed(()=>data.value?ensureImageUrl(data.value.imageUrl):null)
const infoFields=computed(()=>{if(!data.value)return{};const d=data.value;return{'病例ID':`#${d.id}`,'分析时间':d.createdAt,'模型':d.modelUsed||'ResNet50','总置信度':`${((d.confidence||0)*100).toFixed(1)}%`}})
const fmtConf=(c)=>c!=null?`${(c*100).toFixed(1)}%`:'--'
onMounted(()=>{const pages=getCurrentPages();const id=pages[pages.length-1]?.options?.id;if(id)load(id)})
const load=async(id_)=>{loading.value=true;error.value='';try{const id=id_||data.value?.id;const r=await medicalAPI.getReportDetail(id);data.value=r?.data||r}catch(e){error.value='加载失败'}finally{loading.value=false}}
</script>
<style scoped>.page-shell{min-height:100vh;background:#040b16}.body{padding:28rpx}.mb-md{margin-bottom:28rpx}.hero{display:flex;flex-direction:column;gap:14rpx;margin-bottom:36rpx}.sec-kicker{display:inline-flex;padding:6rpx 16rpx;background:rgba(34,211,238,0.08);border:1px solid rgba(34,211,238,0.18);border-radius:999rpx;color:#86e9ff;font-size:22rpx;width:fit-content;font-weight:600}.hero-id{font-size:44rpx;font-weight:800;color:#f7fbff}.hero-stats{display:flex;gap:24rpx}.hs-item{padding:20rpx 28rpx;border-radius:16rpx;background:rgba(7,20,35,0.76);border:1px solid rgba(125,211,252,0.12)}.hsv{font-size:32rpx;font-weight:800;color:#fff;display:block}.hsl{font-size:22rpx;color:rgba(200,218,242,0.65);margin-top:6rpx;display:block}.detail-img{width:100%;min-height:400rpx;border-radius:20rpx;background:rgba(6,17,30,0.9);margin-bottom:28rpx}.card{padding:24rpx;border-radius:22rpx;background:linear-gradient(180deg,rgba(7,21,36,0.94),rgba(4,12,24,0.96));border:1px solid rgba(125,211,252,0.12);margin-bottom:20rpx}.card-title{font-size:30rpx;font-weight:700;color:#f7fbff;margin-bottom:20rpx;display:block}.info-grid{display:flex;flex-wrap:wrap;gap:14rpx}.info-item{padding:18rpx 22rpx;border-radius:14rpx;background:rgba(8,20,35,0.72);border:1px solid rgba(125,211,252,0.08);min-width:calc(50% - 10rpx)}.ii-label{font-size:22rpx;color:rgba(220,235,255,0.72);display:block}.ii-val{font-size:26rpx;color:#f7fbff;font-weight:600;display:block;margin-top:6rpx}.finding-item{padding:20rpx;border-radius:16rpx;background:rgba(8,20,35,0.72);border:1px solid rgba(125,211,252,0.08);margin-bottom:14rpx}.fi-type{font-size:28rpx;color:#f0f6ff;font-weight:600;display:block}.fi-loc{font-size:24rpx;color:rgba(200,218,242,0.65);display:block;margin-top:4rpx}.fi-conf{font-size:22rpx;color:#70d6ff;display:block;margin-top:6rpx}.btn-p{height:80rpx;padding:0 40rpx;border-radius:999rpx;background:linear-gradient(135deg,#5eead4,#38bdf8);color:#032032;font-size:28rpx;font-weight:700;border:none}</style>
